다음 코드에서 출력 결과로 올바른 것을 고르세요.

```python
import requests

class APIError(Exception):
    def __init__(self, status_code, message):
        self.status_code = status_code
        super().__init__(message)

def fetch(url):
    r = requests.get(url)
    if not r.ok:
        raise APIError(r.status_code, f'API 오류: {r.status_code}')
    return r.json()

try:
    data = fetch('https://httpbin.org/status/403')
except APIError as e:
    print(e.status_code)
```

